    <section class="card panel-card notification-history"><div class="notification-card__heading"><span class="notification-card__icon notification-card__icon--accent"><i class="fas fa-history" aria-hidden="true"></i></span><div><span class="ticket-section__eyebrow">Actividad reciente</span><h2>Notificaciones recibidas</h2></div></div><?php if (!$notifications): ?><div class="notification-empty"><span class="notification-empty__icon"><i class="far fa-bell-slash" aria-hidden="true"></i></span><strong>No tienes notificaciones pendientes</strong><p>Cuando se te asigne un ticket o haya cambios, aparecerán aquí.</p></div><?php else: ?><div class="notification-list"><?php foreach ($notifications as $notification): ?><?php $actor = trim((string) ($notification['actor_display_name'] ?? $notification['actor_username'] ?? '')); ?><article class="notification-item <?php echo empty($notification['is_read']) ? 'notification-item--unread' : 'notification-item--read'; ?>"><span class="notification-item__icon"><i class="fas fa-<?php echo $notification['type'] === 'ticket_status' ? 'exchange-alt' : ($notification['type'] === 'ticket_observation' ? 'comment-alt' : 'bell'); ?>" aria-hidden="true"></i></span><div class="notification-item__body"><div class="notification-item__header"><h3><?php echo $escape($notification['title']); ?></h3><?php if (empty($notification['is_read'])): ?><span class="notification-new">Nueva</span><?php endif; ?></div><p><?php echo $escape($notification['message']); ?></p><div class="notification-item__meta"><span><i class="far fa-clock" aria-hidden="true"></i> <?php echo $escape(date('d/m/Y H:i', strtotime($notification['created_at']))); ?></span><?php if ($actor): ?><span><i class="fas fa-user" aria-hidden="true"></i> <?php echo $escape($actor); ?></span><?php endif; ?></div></div><a href="<?php echo $baseUrl; ?>/admin/tickets/<?php echo (int) $notification['ticket_id']; ?>" class="btn btn--secondary notification-item__action">Abrir ticket <i class="fas fa-arrow-right" aria-hidden="true"></i></a></article><?php endforeach; ?></div><?php endif; ?></section>
</section>
